+        return major;
+    }
+
+    public int getMinor() {
+        return minor;
+    }
+
+    public int getRevision() {
+        return revision;
+    }
+
+    public boolean hasQualifier() {
+        return qualifier != null;
+    }
+
+    public Qualifier getQualifier() {
+        return qualifier;
+    }
+
