+                                    failure
+                                );
+                                listener.onResponse(AcknowledgedResponse.TRUE);
+                            }));
+                        return;
+                    }
+                    listener.onResponse(AcknowledgedResponse.TRUE);
+                }, listener::onFailure)
+            );
+        }, listener::onFailure);
